import { GAME_ICONS_ABSTRACT } from './gameIconsAbstract'

export interface IconEntry {
  name: string // display label
  lucide: string // Lucide component name (PascalCase); '' for svg-only entries
  svg?: string // inner SVG content (paths/shapes, no wrapper); used instead of lucide when present
  keywords: string[] // for search
  category: string
  /** Native coordinate system for SVG-only entries (defaults to 0 0 24 24). */
  viewBox?: string
  /** Third-party source used for rendering semantics and attribution. */
  source?: 'game-icons'
}

