// ── Search helper ─────────────────────────────────────────────────────────────

export function searchIcons(query: string, category?: string): IconEntry[] {
  const q = query.toLowerCase().trim()
  let icons = ICON_LIBRARY

  if (category && category !== 'All') {
    icons = icons.filter((i) => i.category === category)
  }

  if (!q) return icons

  return icons
    .map((icon) => {
      let score = 0
      if (icon.name.toLowerCase() === q) score = 100
      else if (icon.name.toLowerCase().startsWith(q)) score = 80
      else if (icon.name.toLowerCase().includes(q)) score = 60
      else if (icon.keywords.some((k) => k === q)) score = 50
      else if (icon.keywords.some((k) => k.startsWith(q))) score = 30
      else if (icon.keywords.some((k) => k.includes(q))) score = 10
      return { icon, score }
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .map((x) => x.icon)
}
